import prettier from 'eslint-config-prettier'
import architecture from './tooling/eslint/architecture.mjs'
import logging from './tooling/eslint/logging.mjs'

// `apps/desktop/.nuxt/eslint.config.mjs` is generated by `nuxt prepare` and
// absent on a fresh checkout; fall back to a no-op wrapper so `pnpm run lint`
// still checks the rest of the repo.
let withNuxt
try {
  ;({ default: withNuxt } = await import('./apps/desktop/.nuxt/eslint.config.mjs'))
} catch {
  withNuxt = (...configs) => configs.flat()
}

export default withNuxt(
  {
    ignores: [
      '.dev/**',
      '**/out/**',
      '**/dist/**',
      '**/.output/**',
      '**/.nuxt/**',
      'coverage/**',
      'test-results/**',
      'playwright-report/**',
      'crates/kchess-contracts/ts/generated/**',
    ],
  },
  {
    files: [
      'apps/desktop/app/**/*.{ts,vue}',
      'crates/kchess-node/js/**/*.ts',
      'crates/kchess-wasm/js/**/*.ts',
      'crates/kchess-contracts/ts/**/*.ts',
      'hosts/node/src/**/*.ts',
      'hosts/node/tests/**/*.ts',
      'apps/cli/src/**/*.ts',
      'apps/desktop/electron/**/*.ts',
      'apps/desktop/contracts/**/*.ts',
      'apps/desktop/tests/**/*.ts',
      'tests/**/*.ts',
    ],
    plugins: { architecture, logging },
    languageOptions: {
      parserOptions: {
        project: [
          './apps/desktop/.nuxt/tsconfig.app.json',
          './apps/desktop/tsconfig.electron.json',
          './crates/kchess-node/tsconfig.json',
          './crates/kchess-wasm/js/tsconfig.json',
          './crates/kchess-contracts/ts/tsconfig.json',
          './hosts/node/tsconfig.json',
          './apps/cli/tsconfig.json',
          './tsconfig.tests.json',
        ],
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      'architecture/boundaries': 'error',
      'logging/no-silent-catch': 'error',
      'logging/no-silent-promise-catch': 'error',
      'logging/no-raw-console': 'error',
      // Renderer `console.log/info` is quiet-cost, not correctness: forbid it in
      // shipped code so the "quiet UI" rule (AGENTS.md) does not regress via dev logs.
      // `warn`/`error` stay allowed (forwarded to the main DiagnosticLog file).
      'no-console': ['error', { allow: ['warn', 'error'] }],
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/no-misused-promises': ['error', { checksVoidReturn: false }],
      '@typescript-eslint/no-explicit-any': 'error',
      // New code avoids `!`; the remaining uses are `ready`-guarded or
      // index accesses with explicit bounds handling. Warn to ratchet down.
      '@typescript-eslint/no-non-null-assertion': 'warn',
    },
  },
  {
    // Plain-JS tooling and tests: AST-only guardrails, no type-aware rules.
    files: ['tests/**/*.mjs', 'tooling/**/*.mjs'],
    plugins: { architecture, logging },
    rules: {
      'architecture/boundaries': 'error',
      'logging/no-silent-catch': 'error',
      'logging/no-silent-promise-catch': 'error',
      'logging/no-raw-console': 'error',
    },
  },
  {
    // Test scaffolding fails loudly on impossible states by construction
    // (`!` on seeded fixture access throws the test); the ratchet targets
    // shipped code, so the rule is off here.
    files: ['tests/**/*.ts', 'apps/desktop/tests/**/*.ts', 'hosts/node/tests/**/*.ts'],
    rules: { '@typescript-eslint/no-non-null-assertion': 'off', 'no-console': 'off' },
  },
  {
    // The logger implementation itself writes to the console; diagnostics.ts
    // mirrors the same exemption as `logging/no-raw-console`.
    files: ['crates/kchess-node/js/logger.ts', 'apps/desktop/electron/main/diagnostics.ts'],
    rules: { 'no-console': 'off' },
  },
  {
    rules: {
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
      ],
      // Existing components intentionally use concise names and optional props.
      'vue/multi-word-component-names': 'off',
      'vue/require-default-prop': 'off',
      // Reactive dictionaries intentionally remove entries by key.
      '@typescript-eslint/no-dynamic-delete': 'off',
    },
  },
  {
    files: ['**/*.ts', 'apps/desktop/app/**/*.vue'],
    // TypeScript checks names, including generated Nuxt auto-imports.
    rules: { 'no-undef': 'off' },
  },
  prettier,
)
